from pathlib import Path
from html import escape
p=Path('outputs/capability-phase-iii')
items=[('capital-thesis-1440','CAPITAL / Thesis'),('capital-assumption-1440','CAPITAL / Assumption active'),('capital-consequence-1440','CAPITAL / Consequence'),('capital-deployment-1440','CAPITAL / Capital deployment'),('capital-thesis-390','CAPITAL / Mobile thesis'),('orchestration-idle-1440','ORCHESTRATION / Idle'),('orchestration-execution-1440','ORCHESTRATION / Execution'),('orchestration-human-gate-1440','ORCHESTRATION / Human gate'),('orchestration-exception-1440','ORCHESTRATION / Exception'),('orchestration-complete-1440','ORCHESTRATION / Complete'),('orchestration-execution-390','ORCHESTRATION / Mobile execution'),('space-plan-1440','SPACE / Plan'),('space-mass-structure-1440','SPACE / Mass and structure'),('space-material-light-1440','SPACE / Material and light'),('space-human-scale-1440','SPACE / Human scale'),('space-occupation-1440','SPACE / Occupation'),('space-occupation-390','SPACE / Mobile occupation')]
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="robots" content="noindex,nofollow"><title>DWS — Phase III Founder Review</title><style>body{margin:0;background:#eae7df;color:#202421;font:16px Arial,sans-serif}header,section{padding:40px 5%}h1{font-size:clamp(36px,5vw,76px);max-width:1000px;letter-spacing:-.04em}p{max-width:850px;line-height:1.7}nav{display:flex;gap:25px;flex-wrap:wrap}a{color:inherit}figure{margin:30px 0 70px}img{display:block;max-width:100%;height:auto}figure.mobile img{max-width:390px}figcaption{margin:15px 0}h2{font-size:32px}small{font-size:12px}</style><header><small>DWS / PHASE III / FOUNDER REVIEW</small><h1>Capital. Orchestration. Space.</h1><p>Three original native demonstrations. Financial data is fictional. Workflow execution is entirely simulated. The pavilion is an unbuilt architectural study. Approved Artifacts 01–06 remain locked. Nothing deployed.</p><nav><a href="/capability-lab/capital">Use Capital</a><a href="/capability-lab/orchestration">Run Orchestration</a><a href="/capability-lab/space">Explore Space</a></nav></header><section><h2>07 / CAPITAL</h2>'''
for i,(name,label) in enumerate(items):
 if i==5:html+='</section><section><h2>08 / ORCHESTRATION</h2>'
 if i==11:html+='</section><section><h2>09 / SPACE</h2>'
 html+=f'<figure class="{"mobile" if "390" in name else "desktop"}"><figcaption>{escape(label)} — {"390 × 844" if "390" in name else "1440 × 1000"}</figcaption><a href="{name}.png"><img src="{name}.png" alt="{escape(label)}" loading="lazy"></a></figure>'
(p/'index.html').write_text(html+'</section></html>')
